const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false
});

let n = 0, m = 0;
let colSums = null;
let linha = 0;

rl.on('line', (line) => {
  if (linha === 0) {
    const parts = line.trim().split(/\s+/);
    n = parseInt(parts[0], 10);
    m = parseInt(parts[1], 10);
    colSums = new Array(m).fill(0);
  } else {
    // para performance, usar split manual
    const parts = line.trim().split(/\s+/);
    for (let j = 0; j < m; j++) {
      colSums[j] += parseInt(parts[j], 10);
    }
  }
  linha++;
});

rl.on('close', () => {
  let best = Infinity;
  for (let j = 0; j < m; j++) {
    if (colSums[j] < best) best = colSums[j];
  }
  console.log(best);
});
